import Foundation

/// Local CLI agents the menu bar knows how to recognize.
///
/// Detection is a **PATH scan**: for each known agent we look for its binary in
/// `$PATH` plus the usual macOS prefixes (Homebrew, `~/.bun/bin`, etc.) and,
/// when found, exec `<binary> --version` to capture a version string. The
/// result is a flat map of `AgentKind → DetectedAgent`.
///
/// This used to be MCP-session based — the bridge queried a `mcp_sessions`
/// table on the gateway and bucketed sessions by `clientInfo.name`. That was
/// the wrong primitive: Behavior execution (lobu#798) spawns the agent CLI as a
/// subprocess, it doesn't open an MCP client. So "is this CLI usable from this
/// Mac" is really "is the binary on disk?", which is what `which` answers.
///
/// Execution (spawn-on-Behavior-fire) lives in `BehaviorDispatcher` — this file's
/// only job is detect + display + persisting the user's default-agent pick.
enum AgentKind: String, CaseIterable, Codable {
    case claudeCode = "claude-code"
    case codex      = "codex"
    case geminiCli  = "gemini-cli"
    case opencode   = "opencode"
    /// Google Antigravity CLI (`agy`). Preferred path for device Behaviors
    /// that should bill/use the user's local Google agent subscription.
    case agy        = "agy"

    /// Executable name to look for on `$PATH`. Picked to match what each
    /// vendor's installer drops in `/usr/local/bin` (or the Homebrew /
    /// `~/.bun/bin` equivalents).
    var binaryName: String {
        switch self {
        case .claudeCode: return "claude"
        case .codex:      return "codex"
        case .geminiCli:  return "gemini"
        case .opencode:   return "opencode"
        case .agy:        return "agy"
        }
    }

    var displayName: String {
        switch self {
        case .claudeCode: return "Claude Code"
        case .codex:      return "Codex CLI"
        case .geminiCli:  return "Gemini CLI"
        case .opencode:   return "OpenCode"
        case .agy:        return "agy (Antigravity)"
        }
    }

    /// Vendor-provided install / docs page. Surfaced as the "Install →" link
    /// on rows where we didn't find the binary so the user has a one-click
    /// path to fix it.
    var installURL: URL {
        switch self {
        case .claudeCode:
            return URL(string: "https://docs.claude.com/en/docs/claude-code/mcp")!
        case .codex:
            return URL(string: "https://github.com/openai/codex")!
        case .geminiCli:
            return URL(string: "https://github.com/google-gemini/gemini-cli")!

