/// Resolve the CLI to spawn for this job. `agent_kind` on the payload
/// wins; falls back to the user's default agent in `UserDefaults`
/// (`lobu.defaultAgent`, set from the menubar — see #797). Returns
/// `nil` when neither source yields a registered executor; the
/// dispatcher then reports completion-with-error so the server can
/// surface the misconfiguration.
func selectExecutor(for payload: BehaviorPayload) -> LocalAgentExecutor? {
    if let raw = payload.behavior.agent_kind,
       let kind = AgentKind(rawValue: raw),
       let ex = executorsByKind[kind] {
        return ex
    }
    if let fallback = LobuDefaultAgentSetting.current,
       let ex = executorsByKind[fallback] {
        return ex
    }
    return nil
}

