/// agent loop.
struct ClaudeCodeExecutor: LocalAgentExecutor {
    var agentKind: AgentKind { .claudeCode }

    /// Path to the `claude` binary. Defaults to a PATH lookup at call time.
    let binary: URL?

    init(binary: URL? = nil) {
        self.binary = binary
    }

    func run(
