/// How a CLI takes its prompt. `claude`, `agy` and `gemini` accept it behind a
/// flag; `opencode` and `codex` take it positionally after a subcommand.
enum PromptDelivery {
    case flag(String)
    case positional(subcommand: [String])
}

/// How the gateway's lobu MCP server is handed to the spawned CLI.
///
/// The config schemas are genuinely vendor-specific, so the cases name their
/// vendor rather than pretending to a shared shape. `.none` is not a gap: those
/// CLIs finalize through the local `lobu` binary, which is the path
/// `DeviceBehaviorPrompt.completionContract` documents first for every agent.
enum McpDelivery {
    case none
    /// `{"mcpServers": {…}}` written 0600 to a temp file and passed by flag.
    case claudeConfigFile(flag: String, extraArgs: [String])
    /// `{"mcp": {…}}` handed over an environment variable — never touches disk.
    case opencodeConfigEnv(variable: String)
}

/// How a CLI spells its own wall-clock cap. Independent of the dispatcher's
/// SIGTERM budget, which every executor gets regardless.
enum TimeoutFlagFormat {
    case bareSeconds
    case secondsSuffix
}

/// Everything that differs between one local agent CLI and another.
///
/// Extracted because `AgyPrintExecutor` was a ~95% copy of `ClaudeCodeExecutor`
/// — same prompt, same PATH augmentation, same drain caps, same
/// SIGTERM→SIGKILL ladder, same exit classification, with only the argv
/// differing. Duplicating ~140 lines per CLI is why three of the five agent
/// kinds `AgentKind` advertises (and the Behavior builder offers) never had an
/// executor at all, and picking one produced a Behavior that failed at
/// dispatch. Adding a CLI is now one `AgentSpec`.
struct AgentSpec {
    let kind: AgentKind
    let promptDelivery: PromptDelivery
    let mcpDelivery: McpDelivery
    /// Flags that let the CLI run without a human answering permission
    /// prompts. Headless Behavior runs cannot answer one.
    let headlessArgs: [String]
    let modelFlag: String?
    let effortFlag: String?
    let permissionModeFlag: String?
    /// Per-run dollar ceiling. Only Claude Code has one, so a configured
    /// `max_budget_usd` is unenforceable on every other CLI — see lobu#2359.
    let budgetFlag: String?
    let timeoutFlag: (flag: String, format: TimeoutFlagFormat)?
    /// Extra fixed arguments appended after the flag-mapped ones.
    let trailingArgs: [String]

    init(
        kind: AgentKind,
        promptDelivery: PromptDelivery,
        mcpDelivery: McpDelivery = .none,
        headlessArgs: [String] = [],
        modelFlag: String? = nil,
        effortFlag: String? = nil,
        permissionModeFlag: String? = nil,
        budgetFlag: String? = nil,
        timeoutFlag: (flag: String, format: TimeoutFlagFormat)? = nil,
        trailingArgs: [String] = []
    ) {
        self.kind = kind
        self.promptDelivery = promptDelivery
        self.mcpDelivery = mcpDelivery
        self.headlessArgs = headlessArgs
        self.modelFlag = modelFlag
        self.effortFlag = effortFlag
        self.permissionModeFlag = permissionModeFlag
        self.budgetFlag = budgetFlag
        self.timeoutFlag = timeoutFlag
        self.trailingArgs = trailingArgs
    }
}

