        effortFlag: "--variant"
    )

    /// Codex CLI. `exec` is already non-interactive; the sandbox flag bounds
    /// what model-generated commands may do. `workspace-write` is chosen over
    /// `--dangerously-bypass-approvals-and-sandbox` deliberately — the
    /// completion contract only needs to spawn `lobu`, not full host access.
    /// Network access is re-enabled because `lobu` must reach the gateway;
    /// codex disables it under `workspace-write` by default.
    static let codex = AgentSpec(
        kind: .codex,
        promptDelivery: .positional(subcommand: ["exec"]),
        headlessArgs: [
            "--skip-git-repo-check",
            "--sandbox", "workspace-write",
            "-c", "sandbox_workspace_write.network_access=true",
        ],
        modelFlag: "-m"
    )

    /// Gemini CLI. `-p` is its documented headless mode; `--approval-mode yolo`
    /// is the only setting that auto-approves tool calls, which a run with no
    /// human attached requires.
    static let geminiCli = AgentSpec(
        kind: .geminiCli,
        promptDelivery: .flag("-p"),
        headlessArgs: ["--approval-mode", "yolo"],
        modelFlag: "-m"
    )

    /// Every kind `AgentKind` advertises. The dispatcher builds its routing
    /// table from this, and the menubar's auto-pick reads the same list, so a
    /// detected-but-unrunnable runtime cannot be selected as a default.
    static let all: [AgentSpec] = [claudeCode, agy, opencode, codex, geminiCli]
}

// MARK: - Spec-driven executor

/// Spawns one local agent CLI according to its `AgentSpec` and returns what the
/// dispatcher needs to report the run.
///
/// Deliberately does no output parsing. Completion is the CLI's job, stated in
/// the prompt by `DeviceBehaviorPrompt.completionContract` — this type only
/// runs the process, bounds it, and classifies how it ended.
struct SpecExecutor: LocalAgentExecutor {
    let spec: AgentSpec
    /// Explicit binary path. Defaults to a PATH lookup at call time.
    let binary: URL?

    var agentKind: AgentKind { spec.kind }

    init(spec: AgentSpec, binary: URL? = nil) {
        self.spec = spec
        self.binary = binary
    }

    func run(
        payload: BehaviorPayload,
        runId: Int,
        timeout: TimeInterval,
        mcp: McpWiring,
        finalizeNudge: String?
    ) async throws -> ExecutorResult {
        let resolvedBinary = try resolveBinary()
        var prompt = DeviceBehaviorPrompt.buildPrompt(payload: payload, runId: runId)
        if let finalizeNudge, !finalizeNudge.isEmpty {
            prompt += "\n\n---\nFINALIZE NUDGE (prior attempt did not complete the window):\n\(finalizeNudge)\n"
        }
        let started = Date()

        // MCP wiring. The config carries the bearer, so the file variant is
        // 0600 and deleted after the run; the env variant never writes it out.
        var mcpConfigURL: URL?
        var mcpEnv: [String: String] = [:]
        var mcpArgs: [String] = []
        switch spec.mcpDelivery {
        case .none:
            break
        case let .claudeConfigFile(flag, extraArgs):
            let url = try ExecutorSupport.writeClaudeMcpConfig(mcp)
            mcpConfigURL = url
            mcpArgs = [flag, url.path] + extraArgs
        case let .opencodeConfigEnv(variable):
            mcpEnv[variable] = ExecutorSupport.opencodeMcpConfigJSON(mcp)
        }
        defer {
            if let mcpConfigURL { try? FileManager.default.removeItem(at: mcpConfigURL) }
        }

        let process = Process()
        process.executableURL = resolvedBinary
        process.arguments = Self.buildArguments(
            spec: spec,
            prompt: prompt,
            config: payload.behavior.execution_config,
            mcpArgs: mcpArgs,
            timeout: timeout
        )
        // Inherit the user's environment. lobu CLI auth is credentials.json
        // (same as the menubar) — do not inject LOBU_API_TOKEN.
        var env = ProcessInfo.processInfo.environment
        // GUI apps often get a stripped PATH; ensure common CLI install dirs.
        let extraPath = [
            "\(NSHomeDirectory())/.local/bin",
            "\(NSHomeDirectory())/.bun/bin",
            "/opt/homebrew/bin",
            "/usr/local/bin",
        ].joined(separator: ":")
        let path = env["PATH"] ?? "/usr/bin:/bin"
        if !path.contains("/.local/bin") {
            env["PATH"] = "\(extraPath):\(path)"
        }
        for (key, value) in mcpEnv { env[key] = value }
        process.environment = env

        let stdoutPipe = Pipe()
        let stderrPipe = Pipe()
        process.standardOutput = stdoutPipe
        process.standardError = stderrPipe
        // No stdin — the CLI gets its prompt through argv.
        process.standardInput = FileHandle.nullDevice

        try process.run()

        // Bounded byte budget: 4 MiB of stdout / 1 MiB of stderr. The CLI's
        // chain-of-thought transcript can easily exceed Process's default pipe
        // buffer (64 KiB on macOS); without draining, the producer blocks on
        // write() and deadlocks the SIGTERM-on-timeout path.
        let stdoutCap = 4 * 1024 * 1024
        let stderrCap = 1 * 1024 * 1024
        let stdoutTask = ExecutorSupport.drainPipe(stdoutPipe, capBytes: stdoutCap)
        let stderrTask = ExecutorSupport.drainPipe(stderrPipe, capBytes: stderrCap)

        // Bounded wait. `Process.terminate()` sends SIGTERM; if the child
        // ignores it, follow with SIGKILL after a short grace window.
        // `interrupt()` is SIGINT-based and gentler, but a CLI's foreground
        // task often swallows it.
        let timedOut = await ExecutorSupport.waitWithTimeout(process: process, timeout: timeout)
        var killedSignal: String? = nil
        if timedOut {
            process.terminate()
            killedSignal = "SIGTERM"
            try? await Task.sleep(nanoseconds: 3_000_000_000)
            if process.isRunning {
                kill(process.processIdentifier, SIGKILL)
                killedSignal = "SIGKILL"
            }
        }

        // Hard deadline on the post-kill EOF wait. If the child spawned
        // grandchildren that inherited our pipes, they can hold the read end
        // open after the direct child is reaped. Give the drain tasks 2
        // seconds to flush, then force-close so the dispatcher can't hang.
        let drainDeadline: TimeInterval = killedSignal == "SIGKILL" ? 2.0 : 60.0
        let (stdoutData, stdoutTruncated) = await ExecutorSupport.awaitDrain(
            stdoutTask, pipe: stdoutPipe, deadline: drainDeadline, cap: stdoutCap
        )
        let (stderrData, _) = await ExecutorSupport.awaitDrain(
            stderrTask, pipe: stderrPipe, deadline: drainDeadline, cap: stderrCap
        )

        let label = spec.kind.binaryName
        let exitCode = process.terminationStatus
        let exitSignal: String? = killedSignal ?? (
            process.terminationReason == .uncaughtSignal ? "signal:\(exitCode)" : nil
        )
        let exitReason: String
        let errorMessage: String?
        if timedOut {
            exitReason = "timeout"
            errorMessage = "\(label) exited via \(killedSignal ?? "SIGTERM") after \(Int(timeout))s timeout"
        } else if exitCode == 0 {
            exitReason = "ok"
            errorMessage = nil
        } else if process.terminationReason == .uncaughtSignal {
            exitReason = "crash"
            errorMessage = "\(label) exited via signal (status=\(exitCode))"
        } else {
            exitReason = "error_message"
            let stderr = String(data: stderrData, encoding: .utf8) ?? ""
            let trimmed = stderr.trimmingCharacters(in: .whitespacesAndNewlines)
            errorMessage = trimmed.isEmpty
                ? "\(label) exited with non-zero status \(exitCode)"
                : "\(label) exited with status \(exitCode): \(trimmed)"
        }

        var stdoutString = String(data: stdoutData, encoding: .utf8) ?? ""
        if stdoutTruncated {
            // Make the truncation visible to the agent reading the output
            // rather than silently cutting mid-sentence.
            stdoutString.append("\n[output truncated]")
        }
        let durationMs = Int(Date().timeIntervalSince(started) * 1000)

        return ExecutorResult(
            output: stdoutString,
            error: errorMessage,
            exitCode: exitCode,
            exitSignal: exitSignal,
            exitReason: exitReason,
            durationMs: durationMs
        )
    }

    private func resolveBinary() throws -> URL {
        if let binary { return binary }
        let name = spec.kind.binaryName
        if let found = ExecutorSupport.locateOnPath(name) { return found }
        throw ExecutorBinaryError.notFound(name)
    }

    /// Assemble the CLI's argv from its spec. Execution-config flags are
    /// appended only when the Behavior configured them and the CLI has a flag
    /// for them; empty strings count as unset so a blank UI field never
    /// produces a flag with an empty value.
    ///
    /// `timeout_seconds` maps to a CLI flag only for CLIs that have one — it is
    /// primarily a wall-clock budget the dispatcher enforces by SIGTERM.
    static func buildArguments(
        spec: AgentSpec,
        prompt: String,
        config: BehaviorPayload.ExecutionConfig?,
        mcpArgs: [String],
        timeout: TimeInterval
    ) -> [String] {
        var args: [String] = []
        var trailingPrompt: String?
        switch spec.promptDelivery {
        case let .flag(flag):
            args += [flag, prompt]
        case let .positional(subcommand):
            args += subcommand
            // Positional prompts must come last, after every flag, or the CLI
            // reads the following flag as another positional.
            trailingPrompt = prompt
        }
        args += spec.headlessArgs
        args += mcpArgs

        if let timeoutFlag = spec.timeoutFlag {
            let seconds = max(1, Int(timeout))
            switch timeoutFlag.format {
            case .bareSeconds: args += [timeoutFlag.flag, "\(seconds)"]
            case .secondsSuffix: args += [timeoutFlag.flag, "\(seconds)s"]
            }
        }

        if let config {
            if let model = config.model, !model.isEmpty, let flag = spec.modelFlag {
                args += [flag, model]
            }
            if let budget = config.max_budget_usd, budget > 0, let flag = spec.budgetFlag {
                args += [flag, String(budget)]
            }
            if let mode = config.permission_mode, !mode.isEmpty, let flag = spec.permissionModeFlag {
                args += [flag, mode]
            }
            if let effort = config.effort, !effort.isEmpty, let flag = spec.effortFlag {
                args += [flag, effort]
            }
        }

        args += spec.trailingArgs
        if let trailingPrompt { args.append(trailingPrompt) }
        return args
    }
}

// MARK: - Shared executor support

/// Process plumbing every executor shares: binary lookup, pipe draining,
/// bounded waits, and the MCP config encoders.
///
/// These were static members of `ClaudeCodeExecutor` that `AgyPrintExecutor`
/// reached across to call — none of it was ever Claude-specific.
enum ExecutorSupport {
    /// Write the spawned CLI's MCP config: the gateway's lobu MCP server with
    /// the device token as bearer. 0600 — the file carries a credential; the
    /// caller deletes it after the run.
    static func writeClaudeMcpConfig(_ mcp: McpWiring) throws -> URL {
        let config: [String: Any] = [
            "mcpServers": [
                "lobu": [
                    "type": "http",
                    "url": mcp.url,
                    "headers": ["Authorization": "Bearer \(mcp.bearer)"],
                ]
            ]
        ]
        let data = try JSONSerialization.data(withJSONObject: config)
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("lobu-behavior-mcp-\(UUID().uuidString).json")
        try data.write(to: url, options: [.atomic])
        try FileManager.default.setAttributes(
            [.posixPermissions: 0o600], ofItemAtPath: url.path
        )
        return url
    }

    /// opencode's config schema: a `mcp` map of remote servers, passed as the
    /// literal content of `OPENCODE_CONFIG_CONTENT` so the bearer never lands
    /// on disk. Falls back to an empty config rather than throwing — a run
    /// without MCP still completes through the `lobu` CLI path.
    static func opencodeMcpConfigJSON(_ mcp: McpWiring) -> String {
        let config: [String: Any] = [
            "mcp": [
                "lobu": [
                    "type": "remote",
                    "url": mcp.url,
                    "headers": ["Authorization": "Bearer \(mcp.bearer)"],
                    "enabled": true,
                ]
            ]
        ]
        guard let data = try? JSONSerialization.data(withJSONObject: config),
              let json = String(data: data, encoding: .utf8) else {
            return "{}"
        }
        return json
    }

    /// Hunt for a binary the same way `LocalAgentDetector` does. Avoids
    /// `which`/shell quoting headaches — pure stdlib stat() loop.
    ///
    /// Through the detector's own prefix list, NOT `$PATH` alone. A LaunchAgent
    /// starts with a stripped `$PATH`, so a `claude` or `agy` installed under
    /// `~/.bun/bin` or `/opt/homebrew/bin` was detected, advertised in the UI,
    /// and then failed every run with "binary not found" — the exact
    /// disagreement between detection and execution that `searchPrefixes`
    /// documents it exists to prevent. One list, so the two cannot drift apart.
    static func locateOnPath(
        _ name: String,
        in dirs: [String] = LocalAgentDetector.searchPrefixes()
    ) -> URL? {
        guard let found = LocalAgentDetector.locate(binary: name, in: dirs) else {
            return nil
        }
        return URL(fileURLWithPath: found)
    }

    /// Drain a Pipe's readable end into a `Data` blob, capped at `capBytes`.
    /// Stops reading once the child closes the pipe (EOF). Excess bytes past
    /// the cap are discarded — a chatty CLI must not blow up process memory.
    /// The returned `truncated` flag lets the caller mark the captured output.
    static func drainPipe(_ pipe: Pipe, capBytes: Int) -> Task<(Data, Bool), Never> {
        Task.detached(priority: .userInitiated) {
            var accumulated = Data()
            var truncated = false
            let handle = pipe.fileHandleForReading
            while true {
                let chunk = handle.availableData
                if chunk.isEmpty { break } // EOF
                if accumulated.count < capBytes {
                    let room = capBytes - accumulated.count
                    if chunk.count > room { truncated = true }
                    accumulated.append(chunk.prefix(room))
                } else {
                    truncated = true
                }
            }
            return (accumulated, truncated)
        }
    }

    /// Await a drain task with a hard wall-clock deadline. If the drain hasn't
    /// finished by then (typically because a grandchild inherited the pipe and
    /// is still alive), force-close the read handle so the drain's blocking
    /// `availableData` returns EOF and the task wraps up.
    static func awaitDrain(
        _ task: Task<(Data, Bool), Never>,
        pipe: Pipe,
        deadline: TimeInterval,
        cap: Int
    ) async -> (Data, Bool) {
        let timeoutTask = Task<Void, Never> {
            try? await Task.sleep(nanoseconds: UInt64(deadline * 1_000_000_000))
            // Closing the read handle unblocks the drain's read syscall.
            try? pipe.fileHandleForReading.close()
        }
        let result = await task.value
        timeoutTask.cancel()
        return result
    }

    /// Poll the process until it exits or the timeout lapses. Returns true when
    /// the timeout was hit. Pure polling (50ms tick) is fine — the child runs
    /// for seconds, and `Process` exposes no AsyncSequence for its state.
    static func waitWithTimeout(process: Process, timeout: TimeInterval) async -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while process.isRunning {
            if Date() > deadline { return true }
            try? await Task.sleep(nanoseconds: 50_000_000)
        }
        return false
    }
}

