    /// Build the Behavior prompt: the Behavior's own prompt (its current
    /// version's instructions) as the task, with the event payload appended as
    /// context — this is what makes a Behavior actually do its job on the
    /// device. No system prompt or role scaffolding is injected; the CLI brings
    /// its own agent loop.
    static func buildPrompt(payload: BehaviorPayload, runId: Int) -> String {
        let behaviorName = payload.behavior.name ?? payload.behavior.slug ?? payload.behavior.id
        let instructions = payload.behavior.prompt?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        var payloadJSON = "{}"
        if let raw = try? JSONSerialization.data(
            withJSONObject: encodePayloadForJSON(payload),
            options: [.prettyPrinted]
        ), let s = String(data: raw, encoding: .utf8) {
            payloadJSON = s
        }
        return """
        \(instructions)

        ---
        Behavior: \(behaviorName)
        Event payload (context; empty for scheduled runs): \(payloadJSON)

        \(completionContract(payload: payload, runId: runId))
        """
    }

    /// The completion contract appended to a Behavior prompt, chosen by how the
    /// run finishes.
    ///
    /// Window runs complete through `completeWindow`: the CLI finalizes the run
    /// itself — through the `lobu` binary, or through the gateway's lobu MCP
    /// server when its `AgentSpec` wires one in — so a run whose agent never
    /// calls it is resumed and then failed by the server. The contract is part
    /// of the task, not a formatting nicety.
    ///
    /// Event turns have no window — the reply IS the work, and the server
    /// completes the run on a clean exit. Handing them the window contract made
    /// the agent mint a canvas for a conversational turn and complete through
    /// the window path, so the server's no-window branch never ran.
    static func completionContract(payload: BehaviorPayload, runId: Int) -> String {
        if payload.isEventTurn {
            return turnContract()
        }
        return completionContract(
            behaviorId: payload.behavior.id,
            runId: runId,
            extractionSchema: payload.behavior.extraction_schema
        )
    }

    /// Convert the `BehaviorPayload` (which contains `AnyJSONValue` values) to a
    /// plain JSON-encodable dictionary so JSONSerialization can dump it. Not via
    /// Codable encode, because `AnyJSONValue` isn't Encodable in this codebase.
    static func encodePayloadForJSON(_ payload: BehaviorPayload) -> [String: Any] {
        let behavior: [String: Any] = [
            "id": payload.behavior.id,
            "name": payload.behavior.name as Any? ?? NSNull(),
            "slug": payload.behavior.slug as Any? ?? NSNull(),
            "agent_kind": payload.behavior.agent_kind as Any? ?? NSNull(),
        ].compactMapValues { $0 }
        var eventPayload: [String: Any] = [:]
        if let p = payload.event.payload {
            // Preserve nested objects/arrays — the Behavior prompt must carry
            // the original JSON structure verbatim, not flattened `NSNull`
            // placeholders for anything that wasn't a primitive.
            for (k, v) in p { eventPayload[k] = v.jsonObject }
        }
        let event: [String: Any] = [
            "trigger_event_id": payload.event.trigger_event_id as Any? ?? NSNull(),
            "fired_at": payload.event.fired_at,
            "payload": eventPayload,
        ]
        let context: [String: Any] = [
            "device": ["worker_id": payload.context.device.worker_id as Any? ?? NSNull()],
            "user": ["user_id": payload.context.user.user_id as Any? ?? NSNull()],
        ]
        return [
            "behavior": behavior,
            "event": event,
            "context": context,
        ]
    }
}

