// First-detection auto-pick: when the user has never chosen a default
// (or just cleared it because their previous pick disappeared), seed
// it with the first installed agent from a fixed preference order.
// We only do this when `defaultAgent == nil` so an explicit user pick
// — including an explicit clear they re-trigger from the menubar —
// never gets stomped on a later refresh.
//
// The candidates are intersected with the kinds that actually have an
// executor. Detection and execution are separate lists, and when this
// drew from detection alone a Mac with only a runtime the dispatcher
// could not spawn would silently auto-select it — every device Behavior
// without an explicit `agent_kind` then failed in `selectExecutor` with
// nothing the user had chosen to explain it.
if defaultAgent == nil, !next.isEmpty {
    let runnable = Set(AgentSpec.all.map(\.kind))
    let preference: [AgentKind] = [.claudeCode, .agy, .codex, .opencode, .geminiCli]
    if let pick = preference.first(where: { next[$0] != nil && runnable.contains($0) }) {
        defaultAgent = pick
    }
