// Standalone regression test for agent-binary lookup.
//
// A LaunchAgent starts with a stripped `$PATH`. `LocalAgentDetector` knows
// this and searches `~/.bun/bin`, `~/.local/bin`, `/opt/homebrew/bin`,
// `/usr/local/bin` and `/usr/bin` on top of it — its own comment says the list
// exists "so detection and execution don't disagree".
//
// Execution disagreed anyway: `locateOnPath` walked `$PATH` ALONE, so a
// `claude` or `agy` installed under `~/.bun/bin` or `/opt/homebrew/bin` was
// detected, offered in the UI, and then failed every Behavior run with
// "binary not found". Both now share one list.
//
// Coverage limit: the default argument of `locateOnPath` binds to
// `searchPrefixes()` at the call site and is not observable from here. This
// pins that the shared list carries the fallbacks and that the lookup walks
// whatever list it is handed; the one-line binding between them is left to
// review.
//
//   swiftc apps/mac/Owletto/BehaviorDispatcher.swift \
//          apps/mac/Owletto/Log.swift \
//          apps/mac/Owletto/LocalAgentDetector.swift \
//          apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Owletto/DeviceConnectorManifests.swift \
//          apps/mac/Tests/BinaryResolutionTests.swift -o /tmp/binary-resolution-test \
//   && /tmp/binary-resolution-test

import Foundation

// Minimal stub for an unrelated LobuClient reference, matching AnyEncodableTests.
extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
}

@main
struct BinaryResolutionTests {
    static var failures = 0

static var failures = 0

static func check(_ cond: Bool, _ msg: String) {
    if !cond {
        failures += 1
        FileHandle.standardError.write(Data("FAIL: \(msg)\n".utf8))
    }
}

static func main() throws {
    let home = NSHomeDirectory()
    let prefixes = LocalAgentDetector.searchPrefixes()

    // The fallbacks are the whole point: without them a stripped-PATH
    // LaunchAgent cannot find a binary the UI already advertised.
    for dir in [
        "\(home)/.bun/bin",
        "\(home)/.local/bin",
        "/opt/homebrew/bin",
        "/usr/local/bin",
        "/usr/bin",
    ] {
        check(prefixes.contains(dir), "search prefixes must include \(dir)")
    }

    // `$PATH` still comes first so a user-installed shadow wins over Homebrew.
    if let pathHead = (ProcessInfo.processInfo.environment["PATH"] ?? "")
        .split(separator: ":").first.map(String.init),
        !pathHead.isEmpty
    {
        check(prefixes.first == pathHead, "$PATH entries must precede the fallbacks")
    }

    // The walk itself: first executable hit wins, non-executables are skipped.
    let root = URL(fileURLWithPath: NSTemporaryDirectory())
        .appendingPathComponent("binres-\(ProcessInfo.processInfo.processIdentifier)")
    let empty = root.appendingPathComponent("empty")
    let real = root.appendingPathComponent("real")
    for dir in [empty, real] {
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
    }
    defer { try? FileManager.default.removeItem(at: root) }

    // A same-named but NON-executable file must not satisfy the lookup —
    // otherwise a stray text file shadows the real binary.
    let decoy = empty.appendingPathComponent("agy")
    FileManager.default.createFile(atPath: decoy.path, contents: Data("not a binary".utf8))
    let binary = real.appendingPathComponent("agy")
    FileManager.default.createFile(
        atPath: binary.path, contents: Data("#!/bin/sh\n".utf8),
        attributes: [.posixPermissions: 0o755])

