// Standalone regression test for spec-driven executor argv construction.
//
// Three of the five agent kinds `AgentKind` advertises — and that the Behavior
// builder offers — had no executor at all: the dispatcher registered exactly
// `claude-code` and `agy`, so selecting Codex, Gemini CLI or opencode produced
// a Behavior that resolved to `nil` in `selectExecutor` and failed at dispatch.
// The registry now derives from `AgentSpec.all`, which is what these pin.
//
// The argv rules that are easy to get wrong and impossible to see failing:
//   - a positional prompt MUST come last, after every flag, or the CLI parses
//     the next flag as a second positional
//   - a flag-mapped execution_config value must be dropped, not emitted empty,
//     when the CLI has no flag for it (only Claude Code has a cost ceiling)
//   - gemini's `--skip-trust` is load-bearing: without it the CLI silently
//     downgrades `--approval-mode yolo` to "default" in an untrusted directory
//     and a headless run cannot approve its own tool calls
//
//   swiftc apps/mac/Owletto/BehaviorDispatcher.swift \
//          apps/mac/Owletto/Log.swift \
//          apps/mac/Owletto/LocalAgentDetector.swift \
//          apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Owletto/DeviceConnectorManifests.swift \
//          apps/mac/Tests/AgentSpecTests.swift -o /tmp/agent-spec-test \
//   && /tmp/agent-spec-test

import Foundation

// Minimal stub for an unrelated LobuClient reference, matching AnyEncodableTests.
extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
}

@main
struct AgentSpecTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("FAIL: \(msg)\n".utf8))
        }
    }

    static func args(
        _ spec: AgentSpec,
        prompt: String = "TASK",
        config: BehaviorPayload.ExecutionConfig? = nil,
        mcpArgs: [String] = [],
        timeout: TimeInterval = 120
    ) -> [String] {
        SpecExecutor.buildArguments(
            spec: spec,
            prompt: prompt,
            config: config,
            mcpArgs: mcpArgs,
            timeout: timeout
        )
    }

    static func config(
        model: String? = nil,
        budget: Double? = nil,
        effort: String? = nil,
        permissionMode: String? = nil
    ) -> BehaviorPayload.ExecutionConfig? {
        let json: [String: Any] = [
            "timeout_seconds": NSNull(),
            "max_budget_usd": budget as Any? ?? NSNull(),
            "model": model as Any? ?? NSNull(),
            "permission_mode": permissionMode as Any? ?? NSNull(),
            "effort": effort as Any? ?? NSNull(),
        ]
        guard let data = try? JSONSerialization.data(withJSONObject: json) else { return nil }
        return try? JSONDecoder().decode(BehaviorPayload.ExecutionConfig.self, from: data)
    }

    static func main() {
        // Every advertised kind must be runnable. This is the regression: the
        // menubar and the Behavior builder both offer five, and the dispatcher
        // used to implement two.
        let specKinds = Set(AgentSpec.all.map(\.kind))
        for kind in AgentKind.allCases {
            check(specKinds.contains(kind), "AgentKind.\(kind.rawValue) has no AgentSpec")
        }
        check(
            AgentSpec.all.count == Set(AgentSpec.all.map(\.kind)).count,
            "AgentSpec.all must not register two specs for one kind"
        )

        // Flag-delivered prompt: the prompt rides directly behind its flag.
        let claude = args(.claudeCode)
        check(claude.first == "-p", "claude prompt flag must lead: \(claude)")
        check(claude.dropFirst().first == "TASK", "claude prompt must follow -p: \(claude)")

        // Positional prompt MUST be last. If a flag follows it, the CLI reads
        // that flag's value as another positional and the run misparses.
        for spec in [AgentSpec.opencode, AgentSpec.codex] {
            let a = args(spec, config: config(model: "m", effort: "high"))
            check(a.last == "TASK", "\(spec.kind.rawValue) positional prompt must be last: \(a)")
            check(a.first != "TASK", "\(spec.kind.rawValue) must emit its subcommand first: \(a)")
        }
        check(args(.opencode).first == "run", "opencode subcommand must be `run`")
        check(args(.codex).first == "exec", "codex subcommand must be `exec`")

        // Headless flags are what let a run with no human attached proceed.
        check(args(.opencode).contains("--auto"), "opencode needs --auto to run headless")
        check(
            args(.agy).contains("--dangerously-skip-permissions"),
            "agy needs its skip-permissions flag to run headless"
        )
        let gemini = args(.geminiCli)
        check(gemini.contains("--approval-mode"), "gemini needs --approval-mode")
        check(gemini.contains("yolo"), "gemini approval mode must be yolo")
        // Observed verbatim without this: "Approval mode overridden to 'default'
        // because the current folder is not trusted".
        check(gemini.contains("--skip-trust"), "gemini yolo is inert without --skip-trust")
        // codex is bounded deliberately rather than bypassing its sandbox.
        check(
            args(.codex).contains("workspace-write"),
            "codex must run sandboxed, not with approvals bypassed"
        )
        check(
            !args(.codex).contains("--dangerously-bypass-approvals-and-sandbox"),
            "codex must not bypass its sandbox"
        )

        // Per-CLI flag names differ; the config must map through the spec.
        let withModel = args(.opencode, config: config(model: "anthropic/claude-sonnet-5"))
        check(withModel.contains("-m"), "opencode model flag is -m, not --model: \(withModel)")
        check(
            !withModel.contains("--model"),
            "opencode must not emit claude's --model spelling: \(withModel)"
        )
        let claudeModel = args(.claudeCode, config: config(model: "sonnet"))
        check(claudeModel.contains("--model"), "claude model flag is --model")

        // Only Claude Code has a cost ceiling. On every other CLI a configured
        // budget is unenforceable and must be dropped, never emitted bare.
        let claudeBudget = args(.claudeCode, config: config(budget: 2.5))
        check(claudeBudget.contains("--max-budget-usd"), "claude must map max_budget_usd")
        for spec in [AgentSpec.opencode, AgentSpec.codex, AgentSpec.geminiCli, AgentSpec.agy] {
            let a = args(spec, config: config(budget: 2.5))
            check(
                !a.contains("--max-budget-usd") && !a.contains("2.5"),
                "\(spec.kind.rawValue) has no cost flag; budget must be dropped: \(a)"
            )
        }

        // Empty strings are unset — a blank UI field must never produce a flag
        // with an empty value, which most CLIs reject outright.
        let blank = args(.claudeCode, config: config(model: "", effort: ""))
        check(!blank.contains(""), "empty config values must not emit empty argv entries: \(blank)")

        // agy is the only CLI with its own wall-clock flag, and it wants a
        // seconds suffix. The dispatcher's SIGTERM budget is separate.
        let agyTimeout = args(.agy, timeout: 90)
        check(agyTimeout.contains("--print-timeout"), "agy must map its own timeout flag")
        check(agyTimeout.contains("90s"), "agy timeout is suffixed seconds: \(agyTimeout)")
        check(
            !args(.claudeCode, timeout: 90).contains("90"),
            "claude has no timeout flag; the dispatcher enforces it"
        )

        // MCP args are injected by the caller and must survive into argv.
        let mcp = args(.claudeCode, mcpArgs: ["--mcp-config", "/tmp/x.json", "--strict-mcp-config"])
        check(mcp.contains("--mcp-config"), "claude mcp args must reach argv")
        check(mcp.contains("--strict-mcp-config"), "claude must not merge the user's global MCP")

        // The two MCP config encoders are vendor-specific shapes, not one schema.
        let wiring = McpWiring(url: "https://gw.example/mcp", bearer: "SECRET")
        let openJSON = ExecutorSupport.opencodeMcpConfigJSON(wiring)
        check(openJSON.contains("\"mcp\""), "opencode config uses the `mcp` key: \(openJSON)")
        check(
            !openJSON.contains("mcpServers"),
            "opencode must not emit claude's mcpServers schema: \(openJSON)"
        )
        check(openJSON.contains("SECRET"), "opencode config must carry the bearer")
        check(openJSON.contains("remote"), "opencode server type is `remote`")

        if failures == 0 {
            print("AgentSpecTests: all checks passed")
        } else {
            FileHandle.standardError.write(Data("AgentSpecTests: \(failures) failure(s)\n".utf8))
            exit(1)
        }
    }
}

