new = """  let pageResult: { has_more: boolean; next_cursor?: { occurred_at: string; id: number } } | undefined;
  // Per-source truncation. Every event source is now capped at the same page
  // size, and each fetches `limit + 1` rows to detect an overflow, so the
  // sentinel has to be trimmed off the secondary sources too — otherwise they
  // return one row more than asked for. Only the primary source gets a cursor;
  // the rest report `has_more` so a caller can see the read was bounded rather
  // than mistaking a truncated window for the whole one.
  const sourcesPage: Record<string, { returned: number; limit: number; has_more: boolean }> = {};
  if (page) {
    for (const sourceName of eventSourceNames) {
      if (sourceName === page.sourceName) continue;
      const rows = results[sourceName] ?? [];
      const hasMore = rows.length > page.limit;
      if (hasMore) results[sourceName] = rows.slice(0, page.limit);
      sourcesPage[sourceName] = {
        returned: (results[sourceName] ?? []).length,
        limit: page.limit,
        has_more: hasMore,
      };
    }
    const rows = results[page.sourceName] ?? [];"""
