export default async (ctx, client) => {
  const out = {};
  for (const id of [5, 71]) {
    try {
      const runs = await client.behaviors.listRuns({ behavior_id: String(id), limit: 4 });
      out[id] = (runs.runs ?? runs).map?.((r) => ({
        id: r.id, status: r.status, started_at: r.started_at, error: r.error_message ?? r.error,
      })) ?? runs;
    } catch (e) { out[id] = { error: String(e).slice(0, 300) }; }
  }
  return out;
};

export default async (ctx, client) => {
  const keys = Object.keys(client.behaviors ?? {});
  return { behaviorMethods: keys };
};

export default async (ctx, client) => {
  const out = {};
  for (const id of [5, 71]) {
    const b = await client.behaviors.get({ behavior_id: String(id) });
    out[id] = {
      name: b.name, status: b.status, agent_kind: b.agent_kind,
      device_worker_id: b.device_worker_id, next_run_at: b.next_run_at,
      last_run: b.last_run ?? b.last_run_at ?? null,
      health: b.health ?? null, error: b.last_error ?? null,
    };
  }
  return out;
};

export default async (ctx, client) => {
  const top = Object.keys(client).filter((k) => /dev|worker|run/i.test(k));
  return { candidates: top, allKeys: Object.keys(client) };
};

export default async (ctx, client) => {
  // watcher_runs / device_workers are not in the query_sql allowlist; try raw query.
