    out.device = await client.query(
      "SELECT id, name, last_seen_at, status FROM device_workers WHERE id = 'e7806c72-9485-4a8c-a619-7e6bdcb14eaf'"
    );
  } catch (e) { out.deviceErr = String(e).slice(0, 200); }
  return out;
};

